samples.source:
classDiagram
  class Document {
    +String title
    +List~Block~ blocks
    +render() String
  }
  class Block {
    <<interface>>
    +toHtml() String
  }
  class Paragraph
  class Diagram {
    +String source
    +toSvg() String
  }
  Document "1" o-- "*" Block
  Block <|.. Paragraph
  Block <|.. Diagram

erDiagram
  AUTHOR ||--o{ ARTICLE : writes
  ARTICLE ||--|{ SECTION : contains
  SECTION ||--o{ DIAGRAM : shows
  AUTHOR {
    string name
    string email
  }
  ARTICLE {
    string slug
    date published
  }
